SELECT CASE WHEN salary >= 118000 THEN 'high' WHEN salary >= 83000 THEN 'mid' ELSE 'low' END AS salary_bucket, MAX(hire_date) AS last_hire_date, ROUND(STDDEV(salary), 2) AS stddev_salary FROM employees WHERE (dept_id = 20 AND manager_id = 26) OR UPPER(email) LIKE '%ANY%' GROUP BY CASE WHEN salary >= 118000 THEN 'high' WHEN salary >= 83000 THEN 'mid' ELSE 'low' END HAVING ROUND(STDDEV(salary), 2) >= 54 ORDER BY stddev_salary DESC, salary_bucket LIMIT 3
